-- 0237: THE MARKET READS THE ROOM — superflex prices for superflex leagues,
-- and every refresh files a report.
--
-- Founder: "We also need to make sure the market prices take into account
-- the league settings, particularly 2QB/Super Flex" and "Let's make a
-- report available in the super admin area that details success of the run
-- and significant changes."
--
-- 0236's board carried one rank — the 1QB dynasty order — so a superflex
-- league priced Josh Allen like a 1QB league would, at a fraction of his
-- real market. Stathead's dynasty pull already ships BOTH markets (value
-- and superflexValue, the only two formats its model offers); the board
-- now stores both orders and player_market_value picks by the league's own
-- lineup.
--
--   • league_is_superflex mirrors the client's leagueSuperflex
--     (engine/classic.ts) so server pricing and app display agree:
--     drip = true (an 8-flex where QBs start anywhere is a QB-rich market);
--     classic reads the lineup spec — SF when two or more spots can start
--     a QB or any multi-position spot includes QB; a classic league with
--     no stored spec reads SF, exactly like the client's spec-less branch.
--   • _market_refresh_apply(rows, as_of) is the ONE door refreshes walk
--     through: it computes what entered, dropped, and moved against the
--     board it replaces, applies the new ranks, and files a
--     market_refresh_log row. Generated refresh migrations are a single
--     call (see scripts/db/gen-market-board.py), so the delta logic lives
--     here — tested by probes — instead of being re-emitted every week.
--   • admin_market_report() serves the log to the super-admin 📈 MARKET
--     panel: when each run landed, how many players, who came, who went,
--     who moved the most.
--
-- LINEAGE: player_market_value patched from its 0236 body (rank choice by
-- league_is_superflex); market_board gains sf_rank.

alter table market_board add column if not exists sf_rank int check (sf_rank >= 1);

create table if not exists market_refresh_log (
  id         bigserial primary key,
  as_of      text not null,                 -- the Stathead market's own date
  applied_at timestamptz not null default now(),
  players    int  not null,
  entered    jsonb not null default '[]'::jsonb,  -- [{slug, rank}]
  dropped    jsonb not null default '[]'::jsonb,  -- [{slug, rank}]  (their OLD rank)
  movers     jsonb not null default '[]'::jsonb,  -- [{slug, from, to}] biggest 1QB swings
  note       text
);
alter table market_refresh_log enable row level security;
-- No policies at all: the log is reachable only through admin_market_report.

-- Does this league price QBs like a superflex market? The server mirror of
-- engine/classic.ts leagueSuperflex — keep the two in lockstep.
create or replace function league_is_superflex(p_league_id uuid) returns boolean
  language sql stable security definer set search_path = public as $$
  select case
    when coalesce(sj ->> 'game_mode', 'drip') <> 'classic' then true
    when sj -> 'roster_slots' is not null then coalesce((
      select count(*) filter (where slot -> 'pos' ? 'QB') >= 2
             or bool_or((slot -> 'pos' ? 'QB') and jsonb_array_length(slot -> 'pos') > 1)
      from jsonb_array_elements(sj -> 'roster_slots') slot), false)
    when sj -> 'roster_classic' is not null then
         coalesce((sj -> 'roster_classic' ->> 'SFLX')::int, 0) >= 1
      or coalesce((sj -> 'roster_classic' ->> 'QB')::int, 0) >= 2
    else true   -- spec-less reads SF, like the client's no-lineup branch
  end
  from (select settings_json as sj from league where id = p_league_id) t;
$$;

create or replace function player_market_value(p_league_id uuid, p_slug text) returns int
  language sql stable security definer set search_path = public as $$
  select greatest(1, round(
    league_salary_cap(p_league_id) * 0.34 * exp(-coalesce(
      (select case when league_is_superflex(p_league_id)
                   then coalesce(mb.sf_rank, mb.rank) else mb.rank end
       from market_board mb where mb.slug = p_slug),
      (select lp.rank from league_pool lp
       where lp.league_id = p_league_id and lp.slug = p_slug)) / 45.0))::int);
$$;

-- The one door a refresh walks through. Rows: [{slug, rank, sf_rank}] —
-- the COMPLETE new board (absence means the player fell off it). Callable
-- by migrations (no auth context) and super admins; nobody else.
create or replace function _market_refresh_apply(p_rows jsonb, p_as_of text)
  returns jsonb language plpgsql security definer set search_path = public as $$
declare n int; ent jsonb; drp jsonb; mov jsonb;
begin
  if auth.uid() is not null and not is_admin() then
    return jsonb_build_object('ok', false, 'error', 'forbidden');
  end if;
  if p_rows is null or jsonb_typeof(p_rows) <> 'array' or jsonb_array_length(p_rows) = 0 then
    return jsonb_build_object('ok', false, 'error', 'no rows');
  end if;

  drop table if exists _mb_new;   -- a second call in the same transaction starts clean
  create temp table _mb_new on commit drop as
  select r ->> 'slug' as slug, (r ->> 'rank')::int as rank, (r ->> 'sf_rank')::int as sf_rank
  from jsonb_array_elements(p_rows) r;

  select coalesce(jsonb_agg(jsonb_build_object('slug', n.slug, 'rank', n.rank) order by n.rank), '[]'::jsonb)
    into ent from _mb_new n where not exists (select 1 from market_board b where b.slug = n.slug);
  select coalesce(jsonb_agg(jsonb_build_object('slug', b.slug, 'rank', b.rank) order by b.rank), '[]'::jsonb)
    into drp from market_board b where not exists (select 1 from _mb_new n where n.slug = b.slug);
  -- Significant movers: a 1QB swing of 15+ spots where either end is inside
  -- the top 200 — the deeps trading places is noise, not news.
  select coalesce(jsonb_agg(jsonb_build_object('slug', slug, 'from', o, 'to', nn) order by d desc), '[]'::jsonb)
    into mov from (
      select b.slug, b.rank as o, n.rank as nn, abs(b.rank - n.rank) as d
      from market_board b join _mb_new n on n.slug = b.slug
      where abs(b.rank - n.rank) >= 15 and least(b.rank, n.rank) <= 200
      order by abs(b.rank - n.rank) desc limit 20) x;

  delete from market_board b where not exists (select 1 from _mb_new n where n.slug = b.slug);
  insert into market_board (slug, rank, sf_rank)
  select slug, rank, sf_rank from _mb_new
  on conflict (slug) do update
    set rank = excluded.rank, sf_rank = excluded.sf_rank, updated_at = now();
  select count(*) into n from _mb_new;

  insert into market_refresh_log (as_of, players, entered, dropped, movers)
  values (p_as_of, n, ent, drp, mov);
  return jsonb_build_object('ok', true, 'players', n,
    'entered', jsonb_array_length(ent), 'dropped', jsonb_array_length(drp),
    'movers', jsonb_array_length(mov));
end $$;

-- The super-admin 📈 MARKET panel: the refresh history, newest first.
create or replace function admin_market_report(p_limit int default 12)
  returns jsonb language plpgsql stable security definer set search_path = public as $$
declare lim int := least(greatest(coalesce(p_limit, 12), 1), 50);
begin
  if not is_admin() then return jsonb_build_object('ok', false, 'error', 'forbidden'); end if;
  return jsonb_build_object('ok', true,
    'board_size', (select count(*) from market_board),
    'runs', (select coalesce(jsonb_agg(r order by r.id desc), '[]'::jsonb) from (
      select id, as_of, applied_at, players, entered, dropped, movers, note
      from market_refresh_log order by id desc limit lim) r));
end $$;

